      assert.ok(existsSync(d), `${relative(APP, d)} fehlt`);
      const q = readFileSync(d, "utf8");
      assert.match(q, /export default englisch\(Seite\);/);
      assert.match(q, new RegExp(`from "@/app/\\(stamm\\)${k === "/" ? "" : k.replace(/[[\]]/g, "\\$&")}/page";`));
