  const opt = (feld) => OPTIONEN[feld].map((x) => ({ id: x, label: optionText(t, feld, x), sub: t.optionSub[feld]?.[x] }));
  const offenOhneKapazitaet = pass ? pass.offen.filter((x) => x !== "kapazitaet").length : 0;

