                ))}
              </select>
              <span aria-hidden="true" className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-ink-500">▾</span>
            </div>
          </div>
        )}
        <Auswahl
          legende={u.modus}
          wert={modus}
          onChange={setModus}
          optionen={[
            { id: "karte", label: u.modi.karte[0], sub: u.modi.karte[1] },
